function fullHome(){return home().replace('images/dress-lian.jpg','images/hero-bride.jpg').replace('فستان ليان بدانتيل ناعم في معرض الخطوط الذهبية','عروس بطرحة طويلة في معرض الخطوط الذهبية').replace('<span class="hero-label"',scene('hero')+'<span class="hero-label"').replace(/<section class="section container">[\s\S]*$/,'')+`<section class="section container">${sectionHeading('THE BRIDAL EDIT','فساتين، تشبه أحلامكِ','dresses.html','جميع الفساتين')}${carousel(dresses.slice(0,6),'latest')}</section><section class="section soft-bg"><div class="container story-split">${photo('embroidery','يدان تطرزان الدانتيل بعناية','image-frame')}<div><span class="eyebrow">A THREAD OF OUR STORY</span><h2>كل تفصيلة تحكي قصة..<br>وقصتنا تبدأ بكِ</h2><p>في الخطوط الذهبية، نؤمن أن فستان الزفاف ليس مجرد تصميم جميل. إنه شعور، وذكرى، وبداية حكاية تليق بكِ. نختار كل خامة ونرسم كل تفصيلة بشغف، لتكوني أنتِ مصدر الإلهام.</p><a href="about.html" class="text-link">تعرّفي على قصتنا ←</a></div></div></section><section class="section container">${sectionHeading('CURATED COLLECTIONS','لكل حلم، مجموعة','collections.html','كل المجموعات')}<div class="grid-four">${collectionCards()}</div></section><section class="section container">${sectionHeading('THE CREATIVE MINDS','إبداع يحمل توقيعهم','designers.html','تعرّفي على المصممين')}<div class="grid-four">${designerCards()}</div></section><section class="section soft-bg"><div class="container center"><span class="eyebrow">LOVE NOTES</span><h2>من حكايات العرائس</h2><p class="small-text">نماذج توضيحية لآراء العرائس في النسخة التجريبية</p><div class="value-grid testimonials">${[['كل تفصيلة كانت تشبهني.. من أول لقاء حتى اللحظة التي ارتديت فيها فستاني.','سارة'],['تجربة هادئة واهتمام بالتفاصيل، جعلت اختيار فستاني ذكرى جميلة.','نورة'],['الفستان الذي حلمت به، بلمسات أكثر جمالاً مما تخيلت.','ريم']].map(([q,n])=>`<blockquote><div class="stars">★★★★★</div>«${q}»<cite>${n} · جدة</cite></blockquote>`).join('')}</div></div></section><div class="section">${banner()}</div>`}
