function catalogPage(){return pageHero('فساتين الزفاف','مجموعتنا المختارة من أجمل التصاميم التي تجمع بين الفخامة والحداثة','hero-bride','THE BRIDAL COLLECTION')+`<section class="container catalog"><div class="filters"><input type="search" id="dress-search" placeholder="ابحثي في فساتين الزفاف..." aria-label="ابحثي في فساتين الزفاف">${select('collection','المجموعة',groups)}${select('sleeve','نوع الأكمام',{long:'أكمام طويلة',short:'أكمام قصيرة',none:'دون أكمام',off:'كتف مكشوف'})}${select('cut','التصميم',{ball:'منفوش',mermaid:'حورية',aline:'A-line',straight:'مستقيم'})}${select('color','اللون',{white:'أبيض',ivory:'عاجي',champagne:'شامبين',pink:'وردي فاتح'})}${select('size','المقاس',{36:'36',38:'38',40:'40',42:'42',44:'44'})}</div><div class="chips"><button class="chip active" data-group="">الكل</button>${Object.entries(groups).map(([v,n])=>`<button class="chip" data-group="${v}">${n}</button>`).join('')}<button class="chip" data-group="2026">موسم 2026</button></div><div class="results-bar"><span id="result-count" role="status"></span><div><button class="text-link" style="background:none;border:0" id="clear-filters">مسح الفلاتر</button><select id="sort" class="sort-select" aria-label="ترتيب الفساتين"><option value="new">الأحدث أولاً</option><option value="name">الاسم أبجدياً</option><option value="favorites">المفضلة أولاً</option></select></div></div><div class="grid-four" id="dress-grid"></div><div id="pagination" class="pagination" aria-label="صفحات الفساتين"></div></section>${banner()}<div style="height:60px"></div>`}
function aboutPage(){return pageHero('أكثر من مجرد فستان..','إنها قصة جمال، شغف، وتميّز منذ اليوم الأول','hero-bride','OUR STORY')+`<section class="section container story-split">${photo('entrance','مدخل معرض الخطوط الذهبية','image-frame')}<div><span class="eyebrow">THE BEGINNING</span><h2>قصتنا</h2><p>انطلقت الخطوط الذهبية من حلم بسيط.. أن نوفر لكل عروس فستاناً يعبر عن شخصيتها ويجعل يومها مميزاً لا يُنسى. من جدة، نصنع مساحة يلتقي فيها الذوق الرفيع بالاهتمام الحقيقي بكل عروس.</p><a class="btn outline" href="collections.html">استكشفي مجموعاتنا ${icon('arrow')}</a></div></section><section class="section soft-bg"><div class="container story-split"><div><span class="eyebrow">CRAFTED WITH LOVE</span><h2>كل تفصيلة تحكي قصة..</h2><p>من اختيار الدانتيل إلى آخر غرزة، تنسج أيدينا تفاصيل تحمل شغفنا بالجمال. نعتني بالقصّة والملمس والانسيابية، لأن جمال الفستان يبدأ من الشعور الذي يمنحكِ إياه.</p></div>${photo('embroidery','تفاصيل التطريز اليدوي','image-frame')}</div></section><section class="section container value-grid"><article><h3>قيمنا</h3><ul class="feature-list"><li>التميّز في كل تفصيلة</li><li>الراحة والخصوصية</li><li>المصداقية والالتزام</li><li>الشغف بالجمال</li><li>الاهتمام بكل عروس</li></ul></article><article><h3>رسالتنا</h3><p>تقديم تجربة فريدة تجمع بين التصميم الراقي والجودة العالية والخدمة الاستثنائية.</p></article><article><h3>رؤيتنا</h3><p>أن نكون الخيار الأول لكل عروس في المملكة وإحدى الوجهات الرائدة في أزياء الزفاف.</p></article></section><section class="container story-split"><div><span class="eyebrow">OUR SIGNATURE</span><h2>إبرة، خيط..<br>وحكاية من ذهب</h2><p>يجمع شعارنا الإبرة وخيطاً يتشكل فستاناً، داخل دائرة ذهبية تحتضن شغفنا بالتفاصيل.</p></div>${scene()}</section><section class="section container story-split">${photo('showroom','المعرض الفاخر وفساتين على مانيكانات','image-frame')}<div><span class="eyebrow">THE GOLDEN EXPERIENCE</span><h2>لماذا الخطوط الذهبية؟</h2><ul class="feature-list"><li>تصاميم حصرية تعكس شخصيتكِ</li><li>خامات عالية الجودة</li><li>خدمة مخصصة لكل عروس</li><li>أجواء راقية وخصوصية تامة</li><li>خبرة طويلة وشغف بالتفاصيل</li></ul><a class="btn" href="booking.html">احجزي موعدكِ الآن</a></div></section><section class="container"><div class="stats"><div class="stat"><strong data-count="5000">0</strong><span>عروس سعيدة</span></div><div class="stat"><strong data-count="500">0</strong><span>تصميم فريد</span></div><div class="stat"><strong data-count="10">0</strong><span>سنوات خبرة</span></div><div class="stat"><strong style="font-family:var(--serif)">جدة</strong><span>المملكة العربية السعودية</span></div></div><p class="center small-text" style="padding:15px">نفخر بثقتكم دائماً</p></section><section class="quote">${photo('quote-bg','عروس وورود بيضاء')}<h2>«ليس مجرد فستان..<br>بل بداية أجمل حكاياتكِ»</h2></section>`}
const benefits=()=>`<div class="benefits">${[['user','تجربة شخصية'],['spark','جودة في التفاصيل'],['cube','تنوع في الأساليب'],['heart','تصاميم حصرية']].map(([i,n])=>`<div>${icon(i)}<span>${n}</span></div>`).join('')}</div>`;
function designersPage(){return pageHero('المصممون','إبداعات عالمية.. بروح خاصة','embroidery','THE CREATIVE MINDS')+`<section class="section container">${sectionHeading('SIGNATURE DESIGNERS','مصممونا المميزون')}<div class="grid-four">${designerCards()}</div></section><section class="section soft-bg"><div class="container">${sectionHeading('DESIGNER COLLECTIONS','مجموعات المصممين')}<div class="grid-four">${collectionCards()}</div></div></section><section class="section container">${benefits()}</section>${banner()}<div style="height:60px"></div>`}
function collectionsPage(){return pageHero('المجموعات','أربع رؤى للجمال.. وفستان واحد يشبهكِ','collection-1','CURATED FOR YOU')+`<section class="section container"><div class="grid-two">${collectionCards()}</div></section>${banner()}<div style="height:60px"></div>`}
const currentDress=dresses.find(d=>d.id===new URLSearchParams(location.search).get('dress'))||dresses[0];
function detailPage(){const d=currentDress;return `<div class="container"><nav class="breadcrumbs" aria-label="مسار التنقل"><a href="index.html">الرئيسية</a><span>›</span><a href="dresses.html">فساتين الزفاف</a><span>›</span><span>فستان ${d.name}</span></nav><section class="detail-layout"><div class="detail-view"><div class="viewer" tabindex="0" aria-label="${d.id==='lian'?'اسحبي أو استخدمي السهمين لتغيير زاوية فستان ليان':'صورة فستان '+d.name}"><img class="viewer-image" id="viewer-image" src="images/${d.id==='lian'?'lian-front':'dress-'+d.id}.jpg" alt="فستان ${d.name} — أمام" draggable="false"><span class="viewer-caption">${d.id==='lian'?'عرض الزوايا التفاعلي · 3D':'تفاصيل التصميم'}</span><div class="viewer-toolbar"><button data-viewer="zoom" aria-label="تكبير الصورة">${icon('search')}</button><button data-viewer="pan" aria-label="تفعيل تحريك الصورة" aria-pressed="false">${icon('move')}</button><button data-viewer="fullscreen" aria-label="عرض ملء الشاشة">${icon('expand')}</button></div><div class="viewer-controls"><button data-viewer="plus" aria-label="تكبير">+</button><button data-viewer="minus" aria-label="تصغير">−</button><button data-viewer="reset" aria-label="إعادة الضبط">${icon('reset')}</button></div>${d.id==='lian'?`<button class="hotspot one" data-modal="lace" aria-label="تفاصيل الصدر"></button><button class="hotspot two" data-modal="lace" aria-label="تفاصيل التطريز"></button><button class="hotspot three" data-modal="lace" aria-label="تفاصيل الدانتيل على الذيل"></button><span class="viewer-angle" id="viewer-angle">360° · أمام</span>`:''}</div>${d.id==='lian'?`<div class="thumbnails">${[['front','أمام'],['back','خلف'],['right','جانب أيمن'],['left','جانب أيسر'],['detail','تفاصيل']].map(([v,n],i)=>`<button class="thumb ${i===0?'active':''}" data-angle="${v}" aria-pressed="${i===0}">${photo('lian-'+v,n+' فستان ليان')}<span>${n}</span></button>`).join('')}</div><div class="viewer-help"><h3>تجربة أقرب إلى الواقع ✧</h3><div class="help-grid">${[['hand','اسحبي للدوران','سحب سلس مع تباطؤ طبيعي'],['search','قرّبي التفاصيل','باعدي بين إصبعين للتكبير'],['expand','عرض كامل','شاهدي كل تفصيلة'],['cube','كل الزوايا','حرّكي شريط الدوران'],['reset','إعادة التعيين','العودة للعرض الأول']].map(([i,n,t])=>`<div>${icon(i)}<strong>${n}</strong><p>${t}</p></div>`).join('')}</div></div>`:''}</div><div class="detail-info"><div class="detail-title"><h1>فستان ${d.name}</h1>${favoriteButton(d)}</div><p class="detail-subtitle">تصميم يجمع بين الفخامة والرقي</p><p class="detail-description">${d.desc} تصميم يرافق أجمل لحظاتكِ ويمنح إطلالتكِ حضوراً لا يُنسى.</p><dl class="specs"><div><dt>المجموعة:</dt><dd>${groups[d.group]}</dd></div><div><dt>المصمم:</dt><dd>${designers[d.designer-1][0]}</dd></div><div><dt>رمز التصميم:</dt><dd dir="ltr">${d.code}</dd></div></dl><div class="choice-label">اللون <span id="selected-color">عاجي</span></div><div class="color-options">${[['أبيض','#faf9f5'],['عاجي','#eee4d4'],['شامبين','#d9c3a6'],['وردي فاتح','#efd8d7']].map(([n,c])=>`<button class="color-choice" data-color="${n}" aria-label="${n}" aria-pressed="${n==='عاجي'}"><span class="swatch" style="background:${c}"></span>${n}</button>`).join('')}</div><div class="choice-label">المقاس <button class="text-link" style="border:0;background:none" data-modal="sizes">دليل المقاسات</button></div><div class="size-options">${d.sizes.map(n=>`<button class="size-choice" data-size="${n}" aria-pressed="${n===38}">${n}</button>`).join('')}</div><div class="detail-buttons"><a class="btn whatsapp" id="price-whatsapp" target="_blank" rel="noopener" href="#">${icon('wa')} استفسري عن السعر عبر واتساب</a><a class="btn" href="booking.html?dress=${d.id}">${icon('calendar')} احجزي موعداً لتجربة الفستان</a><button class="btn outline" data-modal="tryon">${icon('camera')} جربي الفستان عليكِ</button></div><p class="small-text" style="margin-top:15px">تُؤكّد الألوان والمقاسات المتاحة مع المعرض.</p><a class="detail-teaser" href="booking.html">${photo('hero-bride','لحظتكِ الخاصة في المعرض')}<span>لحظة تستحق أن تعيشيها</span></a></div></section><section><div class="tabs" role="tablist" aria-label="معلومات الفستان">${[['description','الوصف'],['design','تفاصيل التصميم'],['materials','المواد والخامات'],['care','العناية بالفستان']].map(([k,n],i)=>`<button id="tab-${k}" role="tab" aria-controls="tab-panel" tabindex="${i===0?'0':'-1'}" aria-selected="${i===0}" data-tab="${k}">${n}</button>`).join('')}</div><div class="tab-content" id="tab-panel" role="tabpanel" aria-labelledby="tab-description">${d.desc}</div>${benefits()}</section><section class="section">${sectionHeading('YOU MAY ALSO LOVE','فساتين مشابهة','dresses.html','كل الفساتين')}${carousel(['reem','dana','malaki','noor','jood'].map(id=>dresses.find(x=>x.id===id)).filter(x=>x.id!==d.id).slice(0,4),'similar')}</section></div>`}
function bookingPage(){return pageHero('موعدكِ مع الحلم','مساحة خاصة بكِ، لنكتشف معاً الفستان الذي يشبهكِ','showroom','A MOMENT JUST FOR YOU')+`<section class="section container form-shell"><div><h2>احجزي تجربتكِ الخاصة</h2><p style="margin:10px 0 25px">أخبرينا قليلاً عنكِ، وسنرتّب معكِ تفاصيل الزيارة.</p><form id="booking-form"><div class="form-grid"><label class="field">الاسم الكامل<input name="name" required autocomplete="name" maxlength="100" placeholder="اسمكِ الكريم"></label><label class="field">رقم الجوال<input name="phone" required inputmode="tel" autocomplete="tel" pattern="05[0-9]{8}" placeholder="05XXXXXXXX" dir="ltr" title="أدخلي رقم جوال سعودي من 10 أرقام يبدأ بـ 05"></label><label class="field">تاريخ الزفاف<input type="date" name="wedding" required></label><label class="field">التاريخ المفضل للزيارة<input type="date" name="date" required></label><label class="field">الوقت المفضل<select name="time" required><option value="">اختاري الوقت</option>${Array.from({length:12},(_,i)=>`<option>${String(i+9).padStart(2,'0')}:00</option>`).join('')}</select></label><label class="field">نوع الخدمة<select name="service" required><option>تجربة فستان</option><option>تفصيل حسب المقاس</option><option>استشارة</option></select></label><label class="field span-two">الفستان المطلوب (اختياري)<select name="dress"><option value="">لم أقرر بعد</option>${dresses.map(d=>`<option value="${d.id}">فستان ${d.name} — ${d.code}</option>`).join('')}</select></label><label class="field span-two">ملاحظاتكِ<textarea name="notes" maxlength="1500" placeholder="أخبرينا عن تفاصيل تحلمين بها..."></textarea></label></div><p class="form-note">سنجهّز طلبكِ لإرساله عبر واتساب. لا يتأكد الموعد إلا بعد رد المعرض. رقم التواصل المعروض تجريبي.</p><button class="btn" type="submit">جهّزي طلب الموعد ${icon('arrow')}</button></form><div id="booking-result" role="status" hidden></div></div><aside class="form-aside">${photo('showroom','مساحة راقية لتجربة فستانكِ','image-frame')}<h3>كل الاهتمام، لكِ وحدكِ</h3><p>جدة · حي الحمراء · شارع فلسطين<br>السبت إلى الخميس، 9 صباحاً – 9 مساءً</p></aside></section>`}
function contactPage(){return pageHero('يسعدنا التواصل معكِ','لكل سؤال، اهتمام.. ولكل زيارة، ترحيب','entrance','LET’S BEGIN YOUR STORY')+`<section class="section container form-shell"><div><span class="eyebrow">VISIT OUR SHOWROOM</span><h2>ننتظركِ في جدة</h2><div class="contact-details"><p>حي الحمراء، شارع فلسطين<br>جدة، المملكة العربية السعودية</p><p>الجوال وواتساب<br><a dir="ltr" href="tel:+966500000000">+966 50 000 0000</a><br><span class="small-text">رقم تجريبي</span></p><a href="mailto:info@goldenlines.com">info@goldenlines.com</a><p>السبت إلى الخميس<br>9:00 صباحاً – 9:00 مساءً</p><a class="btn whatsapp" target="_blank" rel="noopener" href="https://wa.me/966500000000?text=${encodeURIComponent('مرحباً، أود الاستفسار عن المعرض')}">${icon('wa')} تواصلي عبر واتساب</a></div><iframe class="map" title="خريطة حي الحمراء وشارع فلسطين في جدة — موقع تقريبي للحي" loading="lazy" referrerpolicy="no-referrer-when-downgrade" src="https://maps.google.com/maps?q=Al%20Hamra%20Palestine%20Street%20Jeddah&output=embed"></iframe><p class="small-text">الخريطة توضح المنطقة؛ يرجى تأكيد موقع المعرض قبل الزيارة.</p></div><div><h2>اتركي لنا رسالة</h2><p style="margin:12px 0 25px">يسعدنا مساعدتكِ في كل خطوة.</p><form id="contact-form"><div class="form-grid"><label class="field span-two">الاسم<input name="name" required autocomplete="name" maxlength="100"></label><label class="field span-two">البريد الإلكتروني<input name="email" type="email" required autocomplete="email"></label><label class="field span-two">الموضوع<input name="subject" required maxlength="150"></label><label class="field span-two">رسالتكِ<textarea name="message" required maxlength="2500"></textarea></label></div><p class="form-note">تُفتح الرسالة في تطبيق البريد لديكِ لإرسالها إلى المعرض.</p><button class="btn">تجهيز الرسالة ${icon('mail')}</button></form><div id="contact-result" role="status"></div></div></section>`}
const pages={home:fullHome,dresses:catalogPage,about:aboutPage,designers:designersPage,collections:collectionsPage,detail:detailPage,booking:bookingPage,contact:contactPage};
document.querySelector('#app').innerHTML=header()+`<main id="main">${(pages[page]||fullHome)()}</main>`+footer();
document.querySelector('.menu-toggle').addEventListener('click',e=>{const open=document.querySelector('.main-nav').classList.toggle('open');e.currentTarget.setAttribute('aria-expanded',open)});
let toastTimer;function toast(text){const el=document.querySelector('#toast');el.textContent=text;el.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.hidden=true,3500)}
const dialog=document.querySelector('#dialog');let previousFocus;
function openModal(html){previousFocus=document.activeElement;document.querySelector('#dialog-content').innerHTML=html;dialog.showModal()}
dialog.querySelector('.dialog-close').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});dialog.addEventListener('close',()=>previousFocus?.focus());
function refreshFavorites(){document.querySelectorAll('[data-favorite]').forEach(b=>{const saved=favorites.includes(b.dataset.favorite);b.classList.toggle('saved',saved);b.setAttribute('aria-pressed',saved);b.setAttribute('aria-label',`${saved?'إزالة':'إضافة'} فستان ${dresses.find(d=>d.id===b.dataset.favorite)?.name||''} ${saved?'من':'إلى'} المفضلة`)});const count=document.querySelector('#favorite-count');count.textContent=favorites.length;count.hidden=!favorites.length}
const modalContent={sizes:()=>`<h2>دليل المقاسات</h2><p>قياسات تقريبية بالسنتيمتر؛ تؤخذ القياسات الدقيقة في المعرض.</p><table><thead><tr><th>المقاس</th><th>الصدر</th><th>الخصر</th><th>الأرداف</th></tr></thead><tbody>${[[36,84,66,92],[38,88,70,96],[40,92,74,100],[42,96,78,104],[44,100,82,108]].map(r=>`<tr>${r.map(v=>`<td>${v}</td>`).join('')}</tr>`).join('')}</tbody></table><p>اختاري المقاس الأقرب لقياساتكِ، وسنساعدكِ في الضبط.</p>`,lace:()=>`<h2>التفاصيل تصنع الفارق</h2>${photo('lian-detail','تفاصيل دانتيل فستان ليان المكبرة')}`,tryon:()=>`<h2>جربي الفستان عليكِ</h2><p>التجربة الافتراضية بالصور غير متاحة في هذه النسخة. يسعدنا استقبالُكِ في المعرض لتجربة القصّة والخامة واختيار التفاصيل المناسبة لكِ.</p><a class="btn" style="margin-top:22px" href="booking.html?dress=${currentDress.id}">احجزي تجربة خاصة</a>`,language:()=>`<h2>أهلاً بكِ</h2><p>الموقع متاح حالياً باللغة العربية.</p>`,account:()=>`<h2>مساحتكِ الخاصة</h2><p>احفظي الفساتين التي أحببتِها في المفضلة على هذا الجهاز، وعودي إليها حين تشائين. لا تحتاجين لإنشاء حساب.</p><button class="btn" style="margin-top:20px" data-modal="favorites">عرض المفضلة ${icon('heart')}</button>`,favorites:()=>`<h2>فساتين أحببتِها</h2><p class="small-text" style="margin-bottom:20px">تُحفظ اختياراتكِ على هذا الجهاز.</p>${favorites.length?`<div class="grid-two">${dresses.filter(d=>favorites.includes(d.id)).map(card).join('')}</div>`:'<p>ابدئي باكتشاف الفساتين، واضغطي القلب لحفظ ما يلهمكِ.</p><a class="btn" style="margin-top:20px" href="dresses.html">اكتشفي الفساتين</a>'}`};
document.addEventListener('click',e=>{const fav=e.target.closest('[data-favorite]');if(fav){const id=fav.dataset.favorite;favorites=favorites.includes(id)?favorites.filter(x=>x!==id):[...favorites,id];saveStorage('golden-favorites',favorites);refreshFavorites();toast(favorites.includes(id)?'أُضيف الفستان إلى مفضلتكِ':'أُزيل الفستان من المفضلة');if(page==='dresses')renderCatalog()}
 const modal=e.target.closest('[data-modal]');if(modal){if(dialog.open)dialog.close();openModal(modalContent[modal.dataset.modal]())}
 const social=e.target.closest('[data-social]');if(social)openModal(`<h2>${social.dataset.social}</h2><p>سيُضاف رابط حساب المعرض الرسمي هنا بعد تزويدنا به.</p>`);
 const slide=e.target.closest('[data-slide]');if(slide){const el=document.getElementById(slide.dataset.slide);el.scrollBy({left:-Number(slide.dataset.direction)*el.clientWidth*.75,behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth'})}
});refreshFavorites();
